            if r == min_r or r == max_r or c == min_c or c == max_c)

        if is_rect:
            interior = [(rr, cc) for rr in range(min_r+1, max_r) for cc in range(min_c+1, max_c)]
            interior_vals = [(rr, cc, grid[rr][cc]) for rr, cc in interior if grid[rr][cc] != 0 and grid[rr][cc] != color]

            shapes.append({
                'color': color,
                'bbox': (min_r, min_c, max_r, max_c),
                'interior': interior,
                'interior_vals': interior_vals,
            })

    shapes.sort(key=lambda s: (s['bbox'][0], s['bbox'][1]))

    color_counts = Counter(v for row in grid for v in row if v != 0)

    result = [[0] * cols for _ in range(rows)]

    for s in shapes:
        min_r, min_c, max_r, max_c = s['bbox']

        # Draw border
        for r in range(min_r, max_r+1):
            for c in range(min_c, max_c+1):
                if r == min_r or r == max_r or c == min_c or c == max_c:
                    result[r][c] = s['color']

        # Determine fill color
        if s['interior_vals']:
            fill_colors = sorted(set(val for r,c,val in s['interior_vals']))
            fill = fill_colors[0]
        else:
            remaining = [c for c in sorted(color_counts.keys()) 
                        if c not in [cs['color'] for cs in shapes]]
            fill = min(remaining) if remaining else 0

        start_parity = (min_r + min_c) % 2
